//! Which built-in crate a type of the default XML namespace is in (#1285).
//!
//! Every built-in type is named without a prefix, so a document that names a type of a crate the
//! application does not depend on gets an unknown type. This table lets that error name the crate.
//!
//! Only the build-time compiler uses it. The run-time loader keeps its plain error, because the
//! loader is linked into applications and the table must not be. `built_in_types.txt` is
//! generated by the guard of the default XML namespace (`xml_namespaces --write-built-in-types`).

use ferroui_base::metadata::FERRO_XML_NAMESPACE;

/// One line for each crate: its package name, a tab, and its type names separated by spaces.
const TABLE: &str = include_str!("built_in_types.txt");

fn table() -> impl Iterator<Item = (&'static str, &'static str)> {
    TABLE.lines().filter(|line| !line.starts_with('#')).filter_map(|line| line.split_once('\t'))
}

fn crates_of(name: &str) -> Vec<&'static str> {
    table().filter(|(_, names)| names.split(' ').any(|known| known == name)).map(|(package, _)| package).collect()
}

/// What to add to the error of the unknown type `name` of the XML namespace `xml_namespace`.
pub(crate) fn unresolved_type_hint(xml_namespace: &str, name: &str) -> Option<String> {
    if xml_namespace != FERRO_XML_NAMESPACE {
        return None;
    }
    let mut packages = crates_of(name);
    if packages.is_empty() {
        // `{Name}` of a markup extension is the type `NameExtension`.
        packages = crates_of(&format!("{name}Extension"));
    }
    match packages.as_slice() {
        [] => None,
        [package] => Some(format!("{name} is in the crate `{package}`: add it to your dependencies.")),
        several => {
            let listed: Vec<String> = several.iter().map(|package| format!("`{package}`")).collect();
            Some(format!("{name} is in the crates {}: add the one you mean to your dependencies.", listed.join(", ")))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_crate_of_the_table_is_named_for_its_types() {
        let mut crates = 0;
        for (package, names) in table() {
            crates += 1;
            assert!(!names.is_empty(), "{package}");
            for name in names.split(' ') {
                let hint = unresolved_type_hint(FERRO_XML_NAMESPACE, name).expect(name);
                assert!(hint.contains(&format!("`{package}`")), "{name}: {hint}");
            }
        }
        assert!(crates > 10, "{crates}");
    }

    #[test]
    fn only_a_built_in_name_of_the_default_xml_namespace_has_a_hint() {
        assert_eq!(unresolved_type_hint(FERRO_XML_NAMESPACE, "NoSuchTypeAnywhere"), None);
        assert_eq!(unresolved_type_hint("https://example.org/other", "Chart"), None);
    }

    #[test]
    fn a_markup_extension_is_found_by_the_name_a_document_writes() {
        let (_, names) = table().find(|(_, names)| names.split(' ').any(|n| n.ends_with("Extension"))).expect("one");
        let extension = names.split(' ').find(|name| name.ends_with("Extension")).expect("one");
        let written = extension.strip_suffix("Extension").expect("the suffix");
        if crates_of(written).is_empty() {
            assert!(unresolved_type_hint(FERRO_XML_NAMESPACE, written).is_some(), "{written}");
        }
    }

    /// A crate the tests of this crate do not depend on.
    #[cfg(feature = "runtime")]
    const NOT_LINKED: &str = "<Chart xmlns='https://github.com/ferroui'/>";

    #[cfg(feature = "runtime")]
    #[test]
    fn the_run_time_loader_keeps_its_plain_error() {
        let error = crate::FerroRuntimeXamlLoader::parse(NOT_LINKED, None).err().expect("an unknown type");
        assert!(error.message().contains("Unable to resolve type Chart"), "{}", error.message());
        assert!(!error.message().contains("ferroui-controls-charts"), "{}", error.message());
    }

    #[cfg(feature = "runtime")]
    #[test]
    fn the_compiler_names_the_crate() {
        let configuration = ferroui_markup_xaml::RuntimeXamlLoaderConfiguration::default();
        let compiled =
            crate::rust_emitter::compile_documents(&[("Root.xaml", NOT_LINKED)], None, &configuration, &[]);
        let error = compiled[0].source.as_ref().err().expect("an unknown type");
        assert!(error.contains("`ferroui-controls-charts`"), "{error}");
    }
}
